	/**
	 * Default Constructor
	 */
    public AttestationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new AttestationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(AttestationRepository.class) );
		this.validator		= applicationContext.getBean(AttestationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Attestation
	 */
		public Attestation createAttestation( CreateAttestationCommand command ) {

		Attestation entity = new Attestation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAttestationId( command.getAttestationId() );
            entity.setStatement( command.getStatement() );
            entity.setAttestor( command.getAttestor() );
            entity.setDateSigned( command.getDateSigned() );
            entity.setResult( command.getResult() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Attestation {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAttestationCommand
	 * @return		Attestation
	 */
	public Attestation updateAttestation( UpdateAttestationCommand command ) {

		Attestation entity = new Attestation();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAttestationId( command.getAttestationId() );
            entity.setStatement( command.getStatement() );
            entity.setAttestor( command.getAttestor() );
            entity.setDateSigned( command.getDateSigned() );
            entity.setControl( command.getControl() );
            entity.setPolicy( command.getPolicy() );
            entity.setComplianceProgram( command.getComplianceProgram() );
            entity.setResult( command.getResult() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Attestation {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAttestationCommand
	 */
	public void delete( DeleteAttestationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAttestationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Attestation {0} ", id );

	}

	/**
	 * Method to retrieve the Attestation via AttestationFetchOneSummary
	 * @param 	summary AttestationFetchOneSummary
	 * @return 	AttestationFetchOneResponse
	 */
	public Attestation getAttestation( AttestationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "AttestationFetchOneSummary arg cannot be null" );

		Attestation entity = null;
		UUID id = summary.getAttestationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Attestation using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Attestations
	 *
	 * @return 	List<Attestation>
	 */
    public List<Attestation> getAllAttestation() {
		List<Attestation> list = projector.findAll( new FindAllAttestationQuery() );
		return list;
	}

	/**
	 * assign Control on Attestation
	 * @param		command AssignControlToAttestationCommand
	 */
	public void assignControl( AssignControlToAttestationCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignControl(command.getAttestationId(), command.getAssignment());

	}

	/**
	 * unAssign Control on Attestation
	 * @param		command UnAssignControlFromAttestationCommand
	 */
